// executado UMA VEZ na ingestão, no first-touch (P5)
function classificarOrigem(lead) {
  for (const sinal of [S1, S2, S3, S4, S5, S6]) {   // ordem = precedencia
    const hit = sinal.avaliar(lead);
    if (!hit) continue;
    return {
      segmento:  hit.segmento,        // derivado do nivel 2 (P1)
      categoria: hit.categoria,
      detalhe:   hit.detalhe,
      campanha:  hit.campanha,
      razao: {                        // NFR-7 / AC-5.3
        sinalId:      sinal.id,
        sinalNome:    sinal.name,
        campoOrigem:  sinal.field,
        valorBruto:   hit.valorBruto,  // P6
        confianca:    sinal.confidence,
        avaliadoEm:   now()
      }
    };
  }
  // inalcancavel: S6 sempre casa. Se chegar aqui, e bug de implementacao.
  throw new Error('classificacao sem sinal terminal');
}

